import { convert } from '@zapwebp/core';
import { readFile, writeFile } from 'node:fs/promises';

const input = await readFile('logo.svg');
const output = await convert(input, { to: 'webp', quality: 90 });
await writeFile('logo.webp', output);

import { inspectImage, convert } from '@zapwebp/core';

const info = await inspectImage(inputBytes);
if (info.hasAlpha) {
  const webp = await convert(inputBytes, { to: 'webp', clean: true });
} else {
  const avif = await convert(inputBytes, { to: 'avif', quality: 65 });
}

